{"command":"cat > /tmp/probe.py << 'PY'
import subprocess, os, shutil, sys
EXE="/workspace/executable"
def run(args, cwd=None, env=None):
    e=dict(os.environ)
    if env: e.update(env)
    r=subprocess.run([EXE]+args, capture_output=True, text=True, cwd=cwd, env=e)
    return r
def maketree(base, files):
    shutil.rmtree(base, ignore_errors=True)
    os.makedirs(base, exist_ok=True)
    for name,size in files:
        p=os.path.join(base,name)
        d=os.path.dirname(p)
        if d: os.makedirs(d, exist_ok=True)
        if name.endswith("/"):
            os.makedirs(p, exist_ok=True)
        else:
            open(p,"wb").write(b"x"*size)
    return base

def show(args, **kw):
    r=run(args, **kw)
    print("ARGS",args,"RC",r.returncode)
    if r.stdout: print(r.stdout, end="")
    if r.stderr: print("STDERR:",r.stderr, end="")
    print("===")
    return r
PY
