{"command":"python3 - << 'PY'
import pty, os, subprocess, sys
# Run via pty to get tty output
import os, pty
def run_pty(args, env=None):
    e=dict(os.environ)
    if env: e.update(env)
    pid, fd = pty.fork()
    if pid==0:
        os.execve("/workspace/executable", ["/workspace/executable"]+args, e)
    out=b""
    while True:
        try:
            data=os.read(fd, 4096)
            if not data: break
            out+=data
        except OSError:
            break
    _, status=os.waitpid(pid,0)
    return out, status

for args in [["-b","/tmp/tdeep2"],["-A","-b","/tmp/tdeep2"],["-b","/tmp/tree1"]]:
    out,st=run_pty(args)
    print(args, st)
    print(out)
    print("---decoded repr lines---")
    for l in out.split(b"\r\n"):
        print(repr(l))
PY
