// ---------- getopts-like parsing ----------
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum HasArg {
    No,
    Yes,
    Maybe,
}
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Occur {
    Single,
    Multi,
}
#[derive(Clone, Copy)]
struct OptSpec {
    short: char,
    long: &'static str,
    has_arg: HasArg,
    occur: Occur,
}

const OPT_SPECS: &[OptSpec] = &[
    OptSpec { short: 'd', long: "depth", has_arg: HasArg::Maybe, occur: Occur::Single },
    OptSpec { short: 'a', long: "aggr", has_arg: HasArg::Maybe, occur: Occur::Single },
    OptSpec { short: 's', long: "summary", has_arg: HasArg::No, occur: Occur::Single },
    OptSpec { short: 'u', long: "usage", has_arg: HasArg::No, occur: Occur::Single },
    OptSpec { short: 'b', long: "bytes", has_arg: HasArg::No, occur: Occur::Single },
    OptSpec { short: 'f', long: "files-only", has_arg: HasArg::No, occur: Occur::Single },
    OptSpec { short: 'x', long: "exclude", has_arg: HasArg::Yes, occur: Occur::Multi },
    OptSpec { short: 'H', long: "no-hidden", has_arg: HasArg::No, occur: Occur::Single },
    OptSpec { short: 'A', long: "ascii", has_arg: HasArg::No, occur: Occur::Single },
    OptSpec { short: 'h', long: "help", has_arg: HasArg::No, occur: Occur::Single },
    OptSpec { short: 'v', long: "version", has_arg: HasArg::No, occur: Occur::Single },
];

fn spec_by_long(name: &str) -> Option<&'static OptSpec> {
    OPT_SPECS.iter().find(|s| s.long == name || s.short.to_string() == name)
}
fn spec_by_short(c: char) -> Option<&'static OptSpec> {
    OPT_SPECS.iter().find(|s| s.short == c)
}

#[derive(Debug)]
enum ParseFail {
    Unrecognized(String),
    ArgumentMissing(String),
    UnexpectedArgument(String),
    Duplicate(String),
}
impl std::fmt::Display for ParseFail {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ParseFail::Unrecognized(s) => write!(f, "Unrecognized option: '{}'", s),
            ParseFail::ArgumentMissing(s) => write!(f, "Argument to option '{}' missing", s),
            ParseFail::UnexpectedArgument(s) => write!(f, "Option '{}' does not take an argument", s),
            ParseFail::Duplicate(s) => write!(f, "Option '{}' given more than once", s),
        }
    }
}

#[derive(Default, Debug)]
struct Matches {
    // long -> list of arguments (None for flag / no argument given)
    opts: HashMap<&'static str, Vec<Option<String>>>,
    free: Vec<String>,
}
impl Matches {
    fn present(&self, long: &str) -> bool {
        self.opts.contains_key(long)
    }
    fn opt_str(&self, long: &str) -> Option<String> {
        self.opts.get(long).and_then(|v| v.first()).cloned().flatten()
    }
    fn opt_strs(&self, long: &str) -> Vec<String> {
        self.opts
            .get(long)
            .map(|v| v.iter().filter_map(|o| o.clone()).collect())
            .unwrap_or_default()
    }
    fn record(&mut self, spec: &OptSpec, arg: Option<String>) {
        self.opts.entry(spec.long).or_default().push(arg);
    }
}

fn parse_args(args: &[String]) -> Result<Matches, ParseFail> {
    let mut matches = Matches::default();
    let mut i = 0usize;
    let mut only_free = false;
    while i < args.len() {
        let arg = &args[i];
        if only_free {
            matches.free.push(arg.clone());
            i += 1;
            continue;
        }
        if arg == "--" {
            only_free = true;
            i += 1;
            continue;
        }
        if let Some(long_body) = arg.strip_prefix("--") {
            // long option (arg.len() > 2 in character terms; "--x" handled here too,
            // exact "--" was handled above)
            let (name, value) = match long_body.find('=') {
                Some(pos) => (&long_body[..pos], Some(long_body[pos + 1..].to_string())),
                None => (long_body, None),
            };
            let spec = match spec_by_long(name) {
                Some(s) => s,
                None => return Err(ParseFail::Unrecognized(name.to_string())),
            };
            match spec.has_arg {
                HasArg::No => {
                    if value.is_some() {
                        return Err(ParseFail::UnexpectedArgument(name.to_string()));
                    }
                    matches.record(spec, None);
                }
                HasArg::Yes => {
                    if let Some(v) = value {
                        matches.record(spec, Some(v));
                    } else if i + 1 < args.len() {
                        i += 1;
                        matches.record(spec, Some(args[i].clone()));
                    } else {
                        return Err(ParseFail::ArgumentMissing(name.to_string()));
                    }
                }
                HasArg::Maybe => {
                    // long optional arguments are only taken from '='
                    matches.record(spec, value);
                }
            }
            i += 1;
            continue;
        }
        if arg.len() > 1 && arg.starts_with('-') {
            // short option group; iterate over chars after '-'
            let chars: Vec<(usize, char)> = arg[1..].char_indices().collect();
            let mut consumed_next = false;
            let mut idx = 0usize;
            while idx < chars.len() {
                let (byte_pos, c) = chars[idx];
                let spec = match spec_by_short(c) {
                    Some(s) => s,
                    None => return Err(ParseFail::Unrecognized(c.to_string())),
                };
                match spec.has_arg {
                    HasArg::No => {
                        matches.record(spec, None);
                        idx += 1;
                    }
                    HasArg::Yes | HasArg::Maybe => {
                        // remainder of this token after the char, verbatim
                        let rest_start = 1 + byte_pos + c.len_utf8();
                        let rest = &arg[rest_start..];
                        if !rest.is_empty() {
                            matches.record(spec, Some(rest.to_string()));
                        } else if spec.has_arg == HasArg::Yes {
                            if i + 1 < args.len() {
                                i += 1;
                                consumed_next = true;
                                matches.record(spec, Some(args[i].clone()));
                            } else {
                                return Err(ParseFail::ArgumentMissing(c.to_string()));
                            }
                        } else {
                            // Maybe: take next argument only when it does not
                            // look like an option (single "-" counts as a value)
                            let take_next = if i + 1 < args.len() {
                                let nxt = &args[i + 1];
                                nxt == "-" || !nxt.starts_with('-')
                            } else {
                                false
                            };
                            if take_next {
                                i += 1;
                                consumed_next = true;
                                matches.record(spec, Some(args[i].clone()));
                            } else {
                                matches.record(spec, None);
                            }
                        }
                        // rest of the group is consumed as the argument
                        idx = chars.len();
                    }
                }
            }
            let _ = consumed_next;
            i += 1;
            continue;
        }
        // free argument (including "-" and "")
        matches.free.push(arg.clone());
        i += 1;
    }
    // duplicate validation, in option-definition order
    for spec in OPT_SPECS {
        if spec.occur == Occur::Single {
            if let Some(v) = matches.opts.get(spec.long) {
                if v.len() > 1 {
                    return Err(ParseFail::Duplicate(spec.long.to_string()));
                }
            }
        }
    }
    Ok(matches)
}

// ---------- size formatting ----------
fn format_size(size: u64, bytes: bool) -> String {
    if bytes {
        return format!("{} B", size);
    }
    if size < 1024 {
        return format!("{} B", size);
    }
    let mut value = size as f64;
    let mut unit = "B";
    for u in ["KiB", "MiB", "GiB", "TiB"] {
        if value >= 1024.0 {
            value /= 1024.0;
            unit = u;
        } else {
            break;
        }
    }
    if unit == "B" {
        format!("{} B", size)
    } else {
        format!("{:.2} {}", value, unit)
    }
}

// ---------- argument value parsing ----------
fn parse_aggr_value(s: &str) -> Option<u64> {
    let chars: Vec<char> = s.chars().collect();
    if chars.is_empty() {
        return None;
    }
    let (num, mult): (String, u64) = if chars.iter().all(|c| c.is_numeric()) {
        (s.to_string(), 1)
    } else if chars.len() >= 2 && chars[..chars.len() - 1].iter().all(|c| c.is_numeric()) {
        let last = chars[chars.len() - 1];
        let mult: u64 = match last {
            'K' | 'k' => 1024,
            'M' | 'm' => 1024 * 1024,
            'G' | 'g' => 1024 * 1024 * 1024,
            'T' | 't' => 1024 * 1024 * 1024 * 1024,
            _ => 1,
        };
        (chars[..chars.len() - 1].iter().collect(), mult)
    } else {
        return None;
    };
    let parsed: u64 = num.parse().unwrap();
    Some(parsed.wrapping_mul(mult))
}

fn parse_depth_value(s: &str) -> usize {
    s.parse::<u8>().map(|v| v as usize).unwrap_or(1)
}

// ---------- LS_COLORS ----------
#[derive(Default)]
struct LsColors {
    indicators: HashMap<String, String>,
    extensions: HashMap<String, String>,
}

impl LsColors {
    fn from_env() -> LsColors {
        let mut colors = LsColors::default();
        let value = match env::var("LS_COLORS") {
            Ok(v) => v,
            Err(_) => return colors,
        };
        for item in value.split(':') {
            if item.is_empty() {
                continue;
            }
            let mut parts = item.split('=');
            let key = parts.next().unwrap_or("");
            let code = parts.next().unwrap();
            if let Some(stripped) = key.strip_prefix('*') {
                // extension keys: the original parser strips repeated "*."
                // prefixes from the key before using it as the extension
                let ext = key.trim_start_matches("*.");
                let _ = stripped;
                colors.extensions.insert(ext.to_string(), code.to_string());
            } else {
                colors.indicators.insert(key.to_string(), code.to_string());
            }
        }
        colors
    }

    fn indicator(&self, name: &str) -> Option<String> {
        self.indicators.get(name).cloned()
    }

    fn style_for_path(&self, path: &Path) -> Option<String> {
        if path.as_os_str().is_empty() {
            return None;
        }
        let lmd = fs::symlink_metadata(path).ok()?;
        let follow = fs::metadata(path).ok();
        if lmd.file_type().is_symlink() {
            let target_exists = fs::read_link(path)
                .map(|t| Path::new(&t).exists())
                .unwrap_or(false);
            if target_exists {
                if let Some(s) = self.indicator("ln") {
                    return Some(s);
                }
                if let Some(s) = self.indicator("or") {
                    return Some(s);
                }
            } else if let Some(s) = self.indicator("or") {
                return Some(s);
            }
        }
        if let Some(md) = &follow {
            if md.is_dir() {
                if md.permissions().mode() & 0o002 != 0 {
                    if let Some(s) = self.indicator("ow") {
                        return Some(s);
                    }
                }
                if let Some(s) = self.indicator("di") {
                    return Some(s);
                }
            }
        }
        if lmd.permissions().mode() & 0o111 != 0 {
            if let Some(s) = self.indicator("ex") {
                return Some(s);
            }
        }
        if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
            if let Some(s) = self.extensions.get(ext) {
                return Some(s.clone());
            }
        }
        if let Some(md) = &follow {
            if md.is_file() {
                return self.indicator("fi");
            }
        }
        self.indicator("bd")
    }
}

// ---------- names ----------
fn lexical_name(path: &Path) -> String {
    match path.file_name() {
        Some(name) => name.to_str().map(|s| s.to_string()).unwrap_or_else(|| "[invalid name]".to_string()),
        None => path.to_str().map(|s| s.to_string()).unwrap_or_else(|| "[invalid name]".to_string()),
    }
}

fn directory_name(path: &Path) -> String {
    if let Ok(canon) = fs::canonicalize(path) {
        match canon.file_name() {
            Some(name) => {
                return name
                    .to_str()
                    .map(|s| s.to_string())
                    .unwrap_or_else(|| "[invalid name]".to_string())
            }
            None => {
                return canon
                    .to_str()
                    .map(|s| s.to_string())
                    .unwrap_or_else(|| "[invalid name]".to_string())
            }
        }
    }
    lexical_name(path)
}

fn node_name(path: &Path, is_dir: bool) -> String {
    if is_dir {
        directory_name(path)
    } else {
        lexical_name(path)
    }
}

// ---------- tree ----------
#[derive(Clone, Copy)]
struct Options {
    depth: Option<usize>,
    aggr: u64,
    usage: bool,
    bytes: bool,
    files_only: bool,
    no_hidden: bool,
    ascii: bool,
}

struct Node {
    name: String,
    path: PathBuf,
    size: u64,
    children: Vec<Node>,
    aggregated: bool,
}

impl Node {
    fn aggregated(size: u64) -> Node {
        Node {
            name: "<aggregated>".to_string(),
            path: PathBuf::new(),
            size,
            children: Vec::new(),
            aggregated: true,
        }
    }
}

fn entry_size(md: &Metadata, usage: bool) -> u64 {
    if usage {
        md.blocks().wrapping_mul(512)
    } else {
        md.len()
    }
}

/// Recursive size with no filtering (used for nodes at the depth limit).
fn unfiltered_size(path: &Path, own: u64, opts: &Options) -> u64 {
    let mut total = own;
    match fs::read_dir(path) {
        Err(e) => {
            eprintln!("Couldn't read {} ({:?})", lexical_name(path), e.kind());
            total
        }
        Ok(entries) => {
            for entry in entries.flatten() {
                let child = entry.path();
                match fs::symlink_metadata(&child) {
                    Err(e) => {
                        eprintln!("Couldn't read {} ({:?})", lexical_name(&child), e.kind());
                    }
                    Ok(md) => {
                        if md.file_type().is_dir() {
                            total = total.wrapping_add(unfiltered_size(&child, entry_size(&md, opts.usage), opts));
                        } else {
                            total = total.wrapping_add(entry_size(&md, opts.usage));
                        }
                    }
                }
            }
            total
        }
    }
}

fn build_node(path: &Path, depth_remaining: usize, opts: &Options, excludes: &[String]) -> Node {
    let md = match fs::symlink_metadata(path) {
        Err(e) => {
            eprintln!("Couldn't read {} ({:?})", lexical_name(path), e.kind());
            return Node {
                name: lexical_name(path),
                path: path.to_path_buf(),
                size: 0,
                children: Vec::new(),
                aggregated: false,
            };
        }
        Ok(md) => md,
    };
    let is_dir = md.file_type().is_dir();
    let name = node_name(path, is_dir);
    let own = entry_size(&md, opts.usage);
    if !is_dir {
        return Node {
            name,
            path: path.to_path_buf(),
            size: own,
            children: Vec::new(),
            aggregated: false,
        };
    }
    // directory
    if depth_remaining == 0 {
        let size = unfiltered_size(path, own, opts);
        return Node {
            name,
            path: path.to_path_buf(),
            size,
            children: Vec::new(),
            aggregated: false,
        };
    }
    match fs::read_dir(path) {
        Err(e) => {
            // the original reads such a directory twice while building
            eprintln!("Couldn't read {} ({:?})", name, e.kind());
            eprintln!("Couldn't read {} ({:?})", name, e.kind());
            Node {
                name,
                path: path.to_path_buf(),
                size: own,
                children: Vec::new(),
                aggregated: false,
            }
        }
        Ok(entries) => {
            let mut children: Vec<Node> = Vec::new();
            for entry in entries.flatten() {
                let child_path = entry.path();
                if opts.files_only && child_path.is_dir() {
                    continue;
                }
                let child_name = lexical_name(&child_path);
                if opts.no_hidden && child_name.starts_with('.') {
                    continue;
                }
                if excludes.iter().any(|x| x == &child_name) {
                    continue;
                }
                let child = build_node(&child_path, depth_remaining.saturating_sub(1), opts, excludes);
                children.push(child);
            }
            // stable sort by size, descending
            children.sort_by(|a, b| b.size.cmp(&a.size));
            let mut size = own;
            for c in &children {
                size = size.wrapping_add(c.size);
            }
            Node {
                name,
                path: path.to_path_buf(),
                size,
                children,
                aggregated: false,
            }
        }
    }
}

fn aggregate(node: &mut Node, threshold: u64) {
    if node.children.is_empty() {
        return;
    }
    let old = std::mem::take(&mut node.children);
    let mut kept: Vec<Node> = Vec::new();
    let mut small_sum: u64 = 0;
    for child in old {
        if child.size < threshold {
            small_sum = small_sum.wrapping_add(child.size);
        } else {
            kept.push(child);
        }
    }
    for child in &mut kept {
        aggregate(child, threshold);
    }
    if small_sum > 0 {
        kept.push(Node::aggregated(small_sum));
    }
    node.children = kept;
}

