        0x1d242..=0x1d244 | 0x1da00..=0x1da36 | 0x1da3b..=0x1da6c | 0x1da75 |
        0x1da84 | 0x1da9b..=0x1da9f | 0x1daa1..=0x1daaf | 0x1e000..=0x1e006 |
        0x1e008..=0x1e018 | 0x1e01b..=0x1e021 | 0x1e023..=0x1e024 | 0x1e026..=0x1e02a |
        0x1e130..=0x1e136 | 0x1e2ae | 0x1e2ec..=0x1e2ef | 0x1e8d0..=0x1e8d6 |
        0x1e944..=0x1e94a | 0xe0001 | 0xe0020..=0xe007f | 0xe0100..=0xe01ef
    ) {
        return 0;
    }
    // wide / fullwidth ranges
    if matches!(cp,
        0x1100..=0x115f | 0x2329..=0x232a | 0x2e80..=0x303e | 0x3041..=0x33ff |
        0x3400..=0x4dbf | 0x4e00..=0x9fff | 0xa000..=0xa4c6 | 0xac00..=0xd7a3 |
        0xf900..=0xfaff | 0xfe10..=0xfe19 | 0xfe30..=0xfe52 | 0xfe54..=0xfe66 |
        0xfe68..=0xfe6b | 0xff00..=0xff60 | 0xffe0..=0xffe6 | 0x16fe0..=0x16fe4 |
        0x17000..=0x187f7 | 0x18800..=0x18cd5 | 0x1b000..=0x1b152 |
        0x1b164..=0x1b167 | 0x1b170..=0x1b2fb | 0x1f000..=0x1f02f |
        0x1f0a0..=0x1f0ff | 0x1f100..=0x1f1ff | 0x1f200..=0x1f2ff |
        0x1f300..=0x1f64f | 0x1f680..=0x1f6ff | 0x1f900..=0x1f9ff |
        0x1fa70..=0x1faff | 0x20000..=0x2fffd | 0x30000..=0x3fffd
    ) {
        return 2;
    }
    // most emoji presentations not covered above are single-width here in
    // practice for our purposes; keep default
    1
}

fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

fn truncate_to_width(s: &str, limit: usize) -> String {
    let mut used = 0usize;
    let mut out = String::new();
    for c in s.chars() {
        let w = char_width(c);
        if used + w > limit {
            break;
        }
        used += w;
        out.push(c);
    }
    out
}

// ---------- bars ----------
fn compute_own_len(size: u64, denom: u64, base_len: usize) -> usize {
    if denom == 0 {
        return 0;
    }
    let q = size.wrapping_mul(base_len as u64 + 1) / denom;
    let own = q.saturating_sub(1);
    if own > base_len as u64 {
        base_len
    } else {
        own as usize
    }
}

// ---------- printing ----------
struct Printer {
    opts: Options,
    colors: LsColors,
    depth: Option<usize>,
}

impl Printer {
    fn print_root(&self, root: &Node) {
        println!("[ {} {} ]", root.name, format_size(root.size, self.opts.bytes));
        if root.name == "<collection>" {
            self.print_children(root, &[], 0, 0, true, &vec![' '; BAR_WIDTH], 0);
        } else {
            self.print_children(root, &[], 0, 1, true, &vec![' '; BAR_WIDTH], 0);
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn print_children(
        &self,
        parent: &Node,
        ancestors: &[bool],
        parent_graphic_depth: usize,
        child_tree_depth: usize,
        top_level: bool,
        parent_bar: &[char],
        parent_own_len: usize,
    ) {
        if parent.children.is_empty() {
            return;
        }
        if let Some(d) = self.depth {
            if child_tree_depth > d {
                return;
            }
        }
        let child_graphic_depth = parent_graphic_depth + 1;
        if child_graphic_depth > MAX_GRAPHIC_DEPTH {
            return;
        }
        let frozen = !top_level && parent_graphic_depth >= 4;
        let denom_top = parent
            .children
            .iter()
            .map(|c| c.size)
            .max()
            .unwrap_or(0);
        let shade = match parent_graphic_depth {
            1 => '░',
            2 => '▒',
            3 => '▓',
            _ => '█',
        };
        let count = parent.children.len();
        for (idx, child) in parent.children.iter().enumerate() {
            let is_last = idx + 1 == count;
            // bar for this child
            let (bar, own_len): (Vec<char>, usize) = if top_level {
                let own = compute_own_len(child.size, denom_top, BAR_WIDTH);
                let mut b = vec![' '; BAR_WIDTH];
                for slot in b.iter_mut().skip(BAR_WIDTH - own) {
                    *slot = '█';
                }
                (b, own)
            } else if frozen {
                (parent_bar.to_vec(), parent_own_len)
            } else {
                let own = compute_own_len(child.size, parent.size, parent_own_len);
                let mut b = parent_bar.to_vec();
                if parent_own_len > 0 {
                    let start = BAR_WIDTH - parent_own_len;
                    let shade_end = BAR_WIDTH - own;
                    for slot in b.iter_mut().take(shade_end).skip(start) {
                        *slot = shade;
                    }
                    for slot in b.iter_mut().skip(shade_end) {
                        *slot = '█';
                    }
                }
                (b, own)
            };
            // label
            let mut prefix = String::new();
            for last in ancestors {
                if *last {
                    prefix.push_str("   ");
                } else {
                    prefix.push_str("│  ");
                }
            }
            prefix.push_str(if is_last { "└─ " } else { "├─ " });
            let prefix_width = str_width(&prefix);
            let avail = LABEL_WIDTH.saturating_sub(prefix_width);
            let truncated = truncate_to_width(&child.name, avail);
            let label_width = prefix_width + str_width(&truncated);
            let styled = if !self.opts.ascii && !child.aggregated {
                if let Some(code) = self.colors.style_for_path(&child.path) {
                    format!("\x1b[{}m{}\x1b[0m", code, truncated)
                } else {
                    truncated.clone()
                }
            } else {
                truncated.clone()
            };
            let padding = LABEL_WIDTH.saturating_sub(label_width);
            let bar_str: String = bar
                .iter()
                .map(|ch| {
                    if self.opts.ascii {
                        if *ch == ' ' {
                            ' '
                        } else {
                            '#'
                        }
                    } else {
                        *ch
                    }
                })
                .collect();
            let percent = if parent.size == 0 {
                0
            } else {
                child.size.wrapping_mul(100) / parent.size
            };
            println!(
                "{}{}{} │ {}│ {:>3}% {:>13}",
                prefix,
                styled,
                " ".repeat(padding),
                bar_str,
                percent,
                format_size(child.size, self.opts.bytes)
            );
            // recurse
            let mut child_ancestors = ancestors.to_vec();
            child_ancestors.push(is_last);
            self.print_children(
                child,
                &child_ancestors,
                child_graphic_depth,
                child_tree_depth + 1,
                false,
                &bar,
                own_len,
            );
        }
    }
}

// ordering helper retained for clarity (sorting is stable in Rust)
#[allow(dead_code)]
fn cmp_desc(a: &Node, b: &Node) -> Ordering {
    b.size.cmp(&a.size)
}

// ---------- main ----------
pub fn run() -> i32 {
    let args: Vec<String> = env::args().collect();
    let program = if args.is_empty() {
        String::new()
    } else {
        args[0].clone()
    };
    let rest: Vec<String> = if args.len() > 1 { args[1..].to_vec() } else { Vec::new() };
    let matches = match parse_args(&rest) {
        Ok(m) => m,
        Err(e) => {
            print!("{}", usage(&program));
            eprintln!("{}", e);
            return 1;
        }
    };
    if matches.present("help") {
        print!("{}", usage(&program));
        return 0;
    }
    if matches.present("version") {
        println!("{}", VERSION);
        return 0;
    }
    // LS_COLORS is parsed at this point in the original (it can panic on
    // malformed entries, before any path checks)
    let colors = LsColors::from_env();

    let mut paths = matches.free.clone();
    if paths.is_empty() {
        paths.push(".".to_string());
    }
    for p in &paths {
        if !Path::new(p).exists() {
            eprintln!("path {} doesn't exist", p);
            return 1;
        }
    }

    // option extraction
    let mut depth: Option<usize> = None;
    let mut aggr: u64 = 0;
    if matches.present("depth") {
        let v = matches.opt_str("depth").unwrap_or_else(|| "1".to_string());
        depth = Some(parse_depth_value(&v));
    }
    if matches.present("aggr") {
        match matches.opt_str("aggr") {
            Some(v) => match parse_aggr_value(&v) {
                Some(n) => aggr = n,
                None => {
                    eprintln!("invalid argument '{}'", v);
                    return 1;
                }
            },
            None => aggr = 1024 * 1024,
        }
    }
    if matches.present("summary") {
        depth = Some(1);
        aggr = 1024 * 1024;
    }

    let opts = Options {
        depth,
        aggr,
        usage: matches.present("usage"),
        bytes: matches.present("bytes"),
        files_only: matches.present("files-only"),
        no_hidden: matches.present("no-hidden"),
        ascii: matches.present("ascii"),
    };
    let excludes = matches.opt_strs("exclude");
    let depth_remaining = depth.unwrap_or(usize::MAX);

    let mut roots: Vec<Node> = Vec::new();
    for p in &paths {
        let mut root = build_node(Path::new(p), depth_remaining, &opts, &excludes);
        if aggr > 0 {
            aggregate(&mut root, aggr);
        }
        roots.push(root);
    }
    let display_root = if roots.len() == 1 {
        roots.pop().unwrap()
    } else {
        let mut total: u64 = 0;
        for r in &roots {
            total = total.wrapping_add(r.size);
        }
        let mut collection = Node {
            name: "<collection>".to_string(),
            path: PathBuf::new(),
            size: total,
            children: roots,
            aggregated: false,
        };
        collection.children.sort_by(|a, b| b.size.cmp(&a.size));
        collection
    };

    let printer = Printer {
        opts,
        colors,
        depth,
    };
    printer.print_root(&display_root);
    0
}
RS

