import ("bufio";"fmt";"os";"sort";"strconv";"strings")
type Item struct{Name string; Size int}
func main(){
    sc:=bufio.NewScanner(os.Stdin); sc.Buffer(make([]byte,1024*1024),1024*1024)
    var items []Item
    for sc.Scan(){
        parts:=strings.Split(sc.Text(),"\t"); sz,_:=strconv.Atoi(parts[1]); items=append(items,Item{parts[0],sz})
    }
    if os.Getenv("MODE")=="unstable" {
        sort.Slice(items, func(i,j int)bool{return items[i].Size>items[j].Size})
    } else if os.Getenv("MODE")=="stable" {
        sort.SliceStable(items, func(i,j int)bool{return items[i].Size>items[j].Size})
    }
    for _,it:=range items{fmt.Println(it.Name)}
}
