use std::io::{self,BufRead};
#[derive(Clone,Debug)]
struct I{idx:usize,size:u64}
fn main(){
 let mode=std::env::args().nth(1).unwrap();
 let stdin=io::stdin(); let mut v=Vec::new();
 for line in stdin.lock().lines(){let l=line.unwrap(); if l.is_empty(){continue} let mut p=l.split('\t'); let idx:p.next().unwrap().parse().unwrap(); let size:p.next().unwrap().parse().unwrap(); v.push(I{idx,size});}
 match mode.as_str(){
  "desc_unstable"=>v.sort_unstable_by(|a,b|b.size.cmp(&a.size)),
  "asc_unstable_rev"=>{v.sort_unstable_by(|a,b|a.size.cmp(&b.size)); v.reverse();}
