{"command":"python3 - << 'PY'
import subprocess,os,shutil,sys
sys.path.insert(0,'/tmp'); from compare import *
# badutf tree already: /tmp/tbadutf has bad\xffname and good; create .bad and exclusion cases
base=b"/tmp/tbad2"; shutil.rmtree(base,ignore_errors=True); os.makedirs(base)
for name,data in [(b".bad\xff",b"x"*100),(b"bad\xff",b"x"*200),(b"[invalid name]",b"x"*300),(b"good",b"x"*400)]:
    fd=os.open(os.path.join(base,name),os.O_CREAT|os.O_WRONLY); os.write(fd,data); os.close(fd)
for args in [[b"-A",b"-b",base],[b"-A",b"-b",b"-H",base],[b"-A",b"-b",b"-x",b"[invalid name]",base],[b"-A",b"-b",b"-x",b"bad\xff",base]]:
    # Compare harness is text based; recreate via bytes manual
    def run(exe):
        return subprocess.run([exe]+args,capture_output=True)
    a=run(b"/workspace/executable"); b=run(b"/tmp/new_executable")
    print(args, a.returncode==b.returncode and a.stdout==b.stdout and a.stderr==b.stderr)
    if a.stdout!=b.stdout: print(a.stdout,b.stdout)
PY
"}

